-- ============================================================
-- Database Pisang Keju Kaisar (Capstone Asah 2026, Tim A26-CS243)
-- Skema DRAFT + data awal SINTETIS (Data contoh), bukan data penjualan aktual UMKM.
-- Periode data: 2025-11-01 sampai 2026-10-31
-- Cara pakai (PostgreSQL / Neon):  psql "<URL_DATABASE>" -f database_pisang_keju_kaisar.sql
-- Berkas ini membuat 4 tabel dan mengisinya. Jalankan SEKALI pada database kosong.
-- ============================================================

BEGIN;

-- Bila perlu mengulang dari awal (HATI-HATI: menghapus semua data), hilangkan tanda komentar di bawah:
-- DROP TABLE IF EXISTS transaksi, rekap_harian, topping, menu CASCADE;

CREATE TABLE menu (
  id    SERIAL PRIMARY KEY,
  nama  VARCHAR(50) UNIQUE NOT NULL,
  harga INTEGER NOT NULL CHECK (harga > 0)
);

CREATE TABLE topping (
  id    SERIAL PRIMARY KEY,
  nama  VARCHAR(50) UNIQUE NOT NULL,
  harga INTEGER NOT NULL CHECK (harga > 0)
);

-- Satu baris per hari. Tanpa foreign key dari transaksi: rekap baru dibuat saat Tutup Hari,
-- sedangkan transaksi sudah masuk sepanjang hari.
CREATE TABLE rekap_harian (
  tanggal        DATE PRIMARY KEY,
  total_sistem   INTEGER NULL,                 -- NULL pada hari 'hilang' (tidak ada catatan)
  uang_hitungan  INTEGER NULL,                 -- diisi pemilik saat Tutup Hari
  selisih        INTEGER NULL,
  status_tutup   VARCHAR(10) NULL,             -- 'Sesuai' atau 'Selisih'
  hari_hujan     BOOLEAN NULL,                 -- NULL bila tidak diketahui
  status_data    VARCHAR(10) NOT NULL DEFAULT 'lengkap'
                 CHECK (status_data IN ('lengkap','tutup','hilang','sebagian')),
  libur_kuliah   BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE transaksi (
  id_transaksi  VARCHAR(12) PRIMARY KEY,       -- contoh TRX-000001
  tanggal       DATE NOT NULL,
  jam           TIME NULL,                     -- boleh kosong
  menu_id       INTEGER NOT NULL REFERENCES menu(id),
  topping_id    INTEGER NULL REFERENCES topping(id),   -- NULL = tanpa topping
  jumlah        INTEGER NOT NULL CHECK (jumlah > 0),
  harga_satuan  INTEGER NOT NULL,              -- disimpan per transaksi agar riwayat tidak berubah bila harga naik
  harga_topping INTEGER NOT NULL DEFAULT 0,
  total         INTEGER NOT NULL,
  status        VARCHAR(10) NOT NULL DEFAULT 'selesai' CHECK (status IN ('selesai','batal')),
  sumber        VARCHAR(10) NOT NULL DEFAULT 'aplikasi' CHECK (sumber IN ('sintetis','aplikasi'))
);

CREATE INDEX idx_transaksi_tanggal ON transaksi (tanggal);


